import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.Bkgi-hoF.js";const g=JSON.parse('{"title":"Audit Log","description":"","frontmatter":{},"headers":[],"relativePath":"features/audit-log.md","filePath":"features/audit-log.md"}'),o={name:"features/audit-log.md"};function n(s,e,l,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="audit-log" tabindex="-1">Audit Log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit Log&quot;">​</a></h1><p>Every change in the portal is recorded in a tamper-evident audit log. Know exactly who changed what, when, and see the before/after diff.</p><h2 id="what-s-tracked" tabindex="-1">What&#39;s Tracked <a class="header-anchor" href="#what-s-tracked" aria-label="Permalink to &quot;What&#39;s Tracked&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Resources</th></tr></thead><tbody><tr><td>Create</td><td>Configs, segments, API keys, environments, team members, webhooks</td></tr><tr><td>Update</td><td>Config values, targeting rules, rollout %, overrides, schedules, prerequisites</td></tr><tr><td>Delete</td><td>Configs, segments, API keys, environments, webhooks</td></tr><tr><td>State Change</td><td>Lifecycle state transitions (draft → active → stale → archived)</td></tr></tbody></table><h2 id="audit-entry-fields" tabindex="-1">Audit Entry Fields <a class="header-anchor" href="#audit-entry-fields" aria-label="Permalink to &quot;Audit Entry Fields&quot;">​</a></h2><p>Each entry contains:</p><ul><li><strong>Actor</strong> — Who made the change (display name + avatar)</li><li><strong>Action</strong> — create, update, delete, state_change</li><li><strong>Resource</strong> — What was changed (with category chip)</li><li><strong>Timestamp</strong> — When it happened (relative + absolute)</li><li><strong>Old Value</strong> — Previous state (for updates)</li><li><strong>New Value</strong> — Current state (for creates/updates)</li></ul><h2 id="diff-viewer" tabindex="-1">Diff Viewer <a class="header-anchor" href="#diff-viewer" aria-label="Permalink to &quot;Diff Viewer&quot;">​</a></h2><p>For updates, click an entry to see a git-style diff:</p><ul><li><strong>Unified view</strong> — Single column, additions in green, deletions in red</li><li><strong>Side-by-side view</strong> — Two columns comparing old and new</li></ul><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Filter audit entries by:</p><ul><li><strong>Resource category</strong> — configs, segments, api_keys, environments, team, webhooks</li><li><strong>Time range</strong> — Last hour, day, week, month</li></ul><h2 id="infinite-scroll" tabindex="-1">Infinite Scroll <a class="header-anchor" href="#infinite-scroll" aria-label="Permalink to &quot;Infinite Scroll&quot;">​</a></h2><p>The audit log uses infinite scroll pagination — older entries load automatically as you scroll down.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Audit entries are retained based on your project&#39;s configured retention period (default: unlimited on the free tier).</p><h2 id="integration-with-webhooks" tabindex="-1">Integration with Webhooks <a class="header-anchor" href="#integration-with-webhooks" aria-label="Permalink to &quot;Integration with Webhooks&quot;">​</a></h2><p>Audit entries trigger webhook notifications. You can filter webhooks by event type and resource category to get notified only about changes you care about.</p>',19)])])}const f=t(o,[["render",n]]);export{g as __pageData,f as default};
